function e(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function csrf_token():string{if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));return $_SESSION['csrf_token'];}
function verify_csrf():void{$token=$_SESSION['csrf_token']??null;$submitted=$_POST['csrf_token']??null;if(!is_string($token)||$token===''||!is_string($submitted)||$submitted===''||!hash_equals($token,$submitted)){http_response_code(400);exit('انتهت صلاحية النموذج. حدّث الصفحة وأعد المحاولة.');}}
function admin_required():void{if(empty($_SESSION['admin_id'])){header('Location: admin.php');exit;}}
function settings(PDO $pdo):array{$out=[];foreach($pdo->query('SELECT "key","value" FROM settings') as $row)$out[$row['key']]=$row['value'];return $out;}
function site_url(string $path=''):string{$prefix=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/')),'/');return($prefix==='/'?'':$prefix).'/'.$path;}
function absolute_url(string $path=''):string{global $config;$configured=rtrim(trim((string)($config['site_url']??'')),'/');if(filter_var($configured,FILTER_VALIDATE_URL))return$configured.'/'.ltrim($path,'/');$host=(string)($_SERVER['HTTP_HOST']??'');if(!preg_match('/^[A-Za-z0-9.-]+(?::[0-9]{1,5})?$/D',$host))return site_url($path);$https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||((string)($_SERVER['HTTP_X_FORWARDED_PROTO']??'')==='https');return($https?'https':'http').'://'.$host.site_url($path);}
function product_public_url(int $id):string{return absolute_url('product.php?id='.$id);}
function qr_image_url(string $data,int $size=300):string{$size=max(120,min(1000,$size));return'https://api.qrserver.com/v1/create-qr-code/?format=png&size='.$size.'x'.$size.'&data='.rawurlencode($data);}
function base32_encode_secret(string $data):string{$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$out='';$buffer=0;$bits=0;for($i=0,$n=strlen($data);$i<$n;$i++){$buffer=($buffer<<8)|ord($data[$i]);$bits+=8;while($bits>=5){$bits-=5;$out.=$alphabet[($buffer>>$bits)&31];}$buffer&=(1<<$bits)-1;}if($bits>0)$out.=$alphabet[($buffer<<(5-$bits))&31];return$out;}
function base32_decode_secret(string $text):string|false{$text=strtoupper(str_replace([' ','-'],'',trim($text)));if($text===''||!preg_match('/^[A-Z2-7]+=*$/D',$text))return false;$text=rtrim($text,'=');$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$buffer=0;$bits=0;$out='';for($i=0,$n=strlen($text);$i<$n;$i++){$value=strpos($alphabet,$text[$i]);if($value===false)return false;$buffer=($buffer<<5)|$value;$bits+=5;if($bits>=8){$bits-=8;$out.=chr(($buffer>>$bits)&255);}$buffer&=(1<<$bits)-1;}return$out;}
function totp_key():string{global $privateDir;$path=$privateDir.'/autoland.totp.key';if(!is_file($path)){$handle=@fopen($path,'x');if($handle){$newKey=random_bytes(32);fwrite($handle,$newKey);fflush($handle);fclose($handle);@chmod($path,0600);}}$key=@file_get_contents($path);if(!is_string($key)||strlen($key)!==32||!function_exists('openssl_encrypt'))throw new RuntimeException('تعذر فتح مفتاح حماية OTP.');return$key;}
function totp_encrypt_secret(string $secret):string{$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($secret,'aes-256-gcm',totp_key(),OPENSSL_RAW_DATA,$iv,$tag,'',16);if($cipher===false)throw new RuntimeException('تعذر تشفير مفتاح OTP.');return base64_encode($iv.$tag.$cipher);}
function totp_decrypt_secret(string $encoded):string|false{$raw=base64_decode($encoded,true);if(!is_string($raw)||strlen($raw)<29)return false;return openssl_decrypt(substr($raw,28),'aes-256-gcm',totp_key(),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16),'');}
function totp_match_step(string $secret,string $code,int $lastStep=-1):int|false{$code=preg_replace('/\s+/','',trim($code));if(!is_string($code)||!preg_match('/^[0-9]{6}$/D',$code))return false;$key=base32_decode_secret($secret);if($key===false)return false;$current=(int)floor(time()/30);for($drift=-1;$drift<=1;$drift++){$step=$current+$drift;if($step<=$lastStep)continue;$digest=hash_hmac('sha1',pack('N2',0,$step),$key,true);$offset=ord($digest[19])&15;$number=((ord($digest[$offset])&127)<<24)|((ord($digest[$offset+1])&255)<<16)|((ord($digest[$offset+2])&255)<<8)|(ord($digest[$offset+3])&255);$candidate=sprintf('%06d',$number%1000000);if(hash_equals($candidate,$code))return$step;}return false;}
function new_recovery_codes():array{$codes=[];$hashes=[];for($i=0;$i<10;$i++){$raw=strtoupper(bin2hex(random_bytes(6)));$codes[]=substr($raw,0,4).'-'.substr($raw,4,4).'-'.substr($raw,8,4);$hashes[]=password_hash($raw,PASSWORD_DEFAULT);}return[$codes,$hashes];}
function admin_auth_token_key():string{global $privateDir;$path=$privateDir.'/autoland.auth-token.key';if(!is_file($path)){$handle=@fopen($path,'x');if($handle){$newKey=random_bytes(32);fwrite($handle,$newKey);fflush($handle);fclose($handle);@chmod($path,0600);}}$key=@file_get_contents($path);if(!is_string($key)||strlen($key)!==32)throw new RuntimeException('تعذر فتح مفتاح حماية الجلسات الدائمة.');return$key;}
function admin_token_hash(string $token):string{return hash_hmac('sha256',$token,admin_auth_token_key());}
function admin_cookie_path():string{$prefix=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/')),'/');return$prefix===''?'/':$prefix.'/';}
function admin_remember_cookie_name():string{return'autoland_admin_remember';}
function admin_remember_cookie_value():?array{$value=(string)($_COOKIE[admin_remember_cookie_name()]??'');$parts=explode('.',$value,2);if(count($parts)!==2||!preg_match('/^[a-f0-9]{24}$/D',$parts[0])||!preg_match('/^[a-f0-9]{64}$/D',$parts[1]))return null;return[$parts[0],$parts[1]];}
function admin_expire_remember_cookie():void{$https=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';setcookie(admin_remember_cookie_name(),'',['expires'=>time()-3600,'path'=>admin_cookie_path(),'secure'=>$https,'httponly'=>true,'samesite'=>'Strict']);unset($_COOKIE[admin_remember_cookie_name()]);}
function admin_revoke_current_remember_token(PDO $pdo):void{$parts=admin_remember_cookie_value();if($parts)$pdo->prepare('DELETE FROM admin_remember_tokens WHERE selector=?')->execute([$parts[0]]);admin_expire_remember_cookie();}
function admin_revoke_all_remember_tokens(PDO $pdo,int $adminId):void{$pdo->prepare('DELETE FROM admin_remember_tokens WHERE admin_id=?')->execute([$adminId]);admin_expire_remember_cookie();}
if(PHP_SAPI!=='cli'){ob_start(static function(string $html):string{if(!str_contains($html,'</body>')||str_contains($html,'assets/i18n.js'))return$html;return str_replace('</body>','<script src="'.e(site_url('assets/i18n.js')).'"></script></body>',$html);});}
